def set_age(age):
    if age < 0:
        raise ValueError("Age cannot be negative")
    return age

try:
    set_age(-3)
except ValueError as e:
    print("Rejected:", e)
finally:
    print("Done checking")

class Student:
    def __init__(self, name, grade):
        self.name = name
        self.grade = grade

    def info(self):
        return f"{self.name}: {self.grade}"

s = Student("Ana", 92)
print(s.info())   # Ana: 92

class Animal:
    def __init__(self, name):
        self.name = name
    def speak(self):
        return "..."

class Dog(Animal):
    def speak(self):
        return "Woof!"

d = Dog("Bantay")
print(d.name, "says", d.speak())  # Bantay says Woof!

def countdown(n):
    while n > 0:
        yield n
        n -= 1

for num in countdown(3):
    print(num)     # 3 2 1
